const OPS_KEY='turnover-ops-v1';
const OPS_SIDEBAR_KEY='cairbnb-sidebar-collapsed-v1';
const blankState=()=>({properties:[],team:[],jobs:[],inventory:[],expenses:[],messages:[]});
let operationsStorageUnavailable=false;
let db=readDB(), page='overview', calDate=new Date(), detailJobId=null, photoJobId=null, toastTimer, activeCommPropertyId=null, commRole='cleaner';
db.aiSettings={autoFaq:true,digest:'twice_daily',businessName:'CairBnB',...(db.aiSettings||{})};
function readDB(){
 try{
  const raw=localStorage.getItem(OPS_KEY)||'{}';if(raw.length>4_500_000)throw new Error('storage size');
  const saved=JSON.parse(raw),plain=x=>x&&typeof x==='object'&&!Array.isArray(x),str=(v,n=1000)=>String(v??'').slice(0,n),num=v=>Number.isFinite(Number(v))?Number(v):0;
  const rows=(key,max)=>Array.isArray(saved[key])?saved[key].filter(plain).slice(0,max):[];
  const state=blankState();
  state.properties=rows('properties',1000).map(p=>({id:str(p.id,120)||id(),name:str(p.name,200),client:str(p.client,200),address:str(p.address,500),unit:str(p.unit,80),rate:num(p.rate),pay:num(p.pay),access:str(p.access,2000),linen:str(p.linen,500),checklist:(Array.isArray(p.checklist)?p.checklist:[]).slice(0,100).filter(plain).map(c=>({text:str(c.text,300),done:!!c.done}))}));
  state.team=rows('team',500).map(t=>({id:str(t.id,120)||id(),name:str(t.name,150),role:str(t.role,80),phone:str(t.phone,80),rate:num(t.rate)}));
  state.jobs=rows('jobs',10000).map(j=>({id:str(j.id,120)||id(),propertyId:str(j.propertyId,120),date:str(j.date,20),time:str(j.time,100),cleanerId:str(j.cleanerId,120),fee:num(j.fee),pay:num(j.pay),note:str(j.note,2000),status:['scheduled','in_progress','completed'].includes(j.status)?j.status:'scheduled',invoiceStatus:['paid','unpaid'].includes(j.invoiceStatus)?j.invoiceStatus:'unpaid',checklist:(Array.isArray(j.checklist)?j.checklist:[]).slice(0,100).filter(plain).map(c=>({text:str(c.text,300),done:!!c.done})),photos:(Array.isArray(j.photos)?j.photos:[]).filter(x=>typeof x==='string'&&x.length<500_000&&/^data:image\/jpeg;base64,[a-z\d+/]+=*$/i.test(x)).slice(0,6),damage:str(j.damage,3000),completedAt:str(j.completedAt,40),icalSummary:str(j.icalSummary,300)}));
  state.inventory=rows('inventory',2000).map(x=>({id:str(x.id,120)||id(),name:str(x.name,150),category:str(x.category,80),propertyId:str(x.propertyId,120),qty:num(x.qty),min:num(x.min),unit:str(x.unit,50)}));
  state.expenses=rows('expenses',10000).map(x=>({id:str(x.id,120)||id(),name:str(x.name,150),amount:num(x.amount),category:str(x.category,80),date:str(x.date,20),note:str(x.note,1000)}));
  state.messages=rows('messages',5000).map(m=>({id:str(m.id,120)||id(),isConversation:!!m.isConversation,propertyId:str(m.propertyId,120),text:str(m.text,2000),sender:str(m.sender,100),senderRole:str(m.senderRole,40),isAI:!!m.isAI,needsOwner:!!m.needsOwner,reason:str(m.reason,200),resolved:!!m.resolved,urgent:!!m.urgent,date:str(m.date,20),createdAt:str(m.createdAt,40),author:str(m.author,100),jobId:str(m.jobId,120)}));
  state.aiSettings={autoFaq:saved.aiSettings?.autoFaq!==false,digest:['twice_daily','daily','urgent_only'].includes(saved.aiSettings?.digest)?saved.aiSettings.digest:'twice_daily',businessName:'CairBnB'};
  return state;
 }catch{operationsStorageUnavailable=true;return blankState();}
}
function saveDB(){if(operationsStorageUnavailable){setTimeout(()=>showToast('Browser storage is unavailable or contains damaged data; changes were not saved.'),0);return false;}try{const serialized=JSON.stringify(db);if(serialized.length>1_000_000)throw new Error('limit');localStorage.setItem(OPS_KEY,serialized);return true;}catch{db=readDB();setTimeout(()=>showToast('Could not save: browser storage is full or blocked. Remove large photos, then try again.'),0);return false;}}
function safe(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(n)||0);}
function id(){return crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;}
function showToast(s){let x=document.getElementById('opsToast');x.textContent=s;x.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>x.classList.remove('show'),2800);}
function dateText(s,opts={month:'short',day:'numeric',year:'numeric'}){if(!s)return '—';let d=new Date(`${s}T12:00:00`);return isNaN(d)?safe(s):d.toLocaleDateString('en-US',opts);}
function localKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function today(){return localKey();}
function propName(pid){return db.properties.find(p=>p.id===pid)?.name||'Property not set';}
function teamName(tid){return db.team.find(t=>t.id===tid)?.name||'Unassigned';}
function propsOptions(value=''){return '<option value="">Choose a property</option>'+db.properties.map(p=>`<option value="${safe(p.id)}" ${p.id===value?'selected':''}>${safe(p.name)}</option>`).join('');}
function teamOptions(value=''){return '<option value="">Unassigned</option>'+db.team.map(t=>`<option value="${safe(t.id)}" ${t.id===value?'selected':''}>${safe(t.name)}</option>`).join('');}
function statusBadge(s){return `<span class="badge badge-${safe(s==='in_progress'?'progress':s)}">${s==='in_progress'?'In progress':s==='completed'?'Completed':s==='scheduled'?'Scheduled':safe(s||'Draft')}</span>`;}
function header(eyebrow,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action?`<div class="head-actions">${action}</div>`:''}</div>`;}
function card(title,desc,body,action=''){return `<section class="card"><div class="card-head"><div><h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${action}</div>${body}</section>`;}
function empty(title,desc,button=''){return `<div class="empty-box"><strong>${title}</strong>${desc}${button?`<div style="margin-top:12px">${button}</div>`:''}</div>`;}
function addJobButton(label='＋ Add turnover'){return `<button class="solid-btn" data-action="add-job">${label}</button>`;}
function jobsForRange(start,end){return db.jobs.filter(j=>j.date>=start&&j.date<=end).sort((a,b)=>a.date.localeCompare(b.date));}
function miniJob(j){return `<div class="job-row"><div><div class="job-name">${safe(propName(j.propertyId))}</div><div class="job-sub">${safe(j.time||'Flexible')} · ${safe(j.checklist?.filter(c=>c.done).length||0)}/${safe(j.checklist?.length||0)} checklist items</div></div><div class="job-when">${dateText(j.date)}</div><div class="job-team">${safe(teamName(j.cleanerId))}</div><div>${statusBadge(j.status)}</div></div>`;}
function overview(){
 const todays=db.jobs.filter(j=>j.date===today()), open=db.jobs.filter(j=>j.status!=='completed'), outstanding=db.jobs.filter(j=>j.status==='completed').reduce((n,j)=>n+(j.invoiceStatus==='paid'?0:Number(j.fee)||0),0), low=db.inventory.filter(i=>Number(i.qty)<=Number(i.min));
 const todayRows=todays.length?todays.map(miniJob).join(''):empty('A little breathing room today','No turnovers are scheduled for today.',addJobButton());
 const weekStart=new Date();weekStart.setDate(weekStart.getDate()-weekStart.getDay());const weekEnd=new Date(weekStart);weekEnd.setDate(weekEnd.getDate()+6);
 const week=jobsForRange(weekStart.toISOString().slice(0,10),weekEnd.toISOString().slice(0,10));
 const updates=db.messages.filter(m=>m.isConversation&&m.needsOwner&&!m.resolved).slice(-4).reverse().map(m=>`<div class="activity-item"><i class="activity-dot"></i><div><strong>${safe(propName(m.propertyId))} · ${safe(m.reason||'Owner review')}</strong><small>${safe(m.text)} · ${dateText(m.date,{month:'short',day:'numeric'})}</small></div></div>`).join('')||empty('No exceptions to resolve','Routine unit questions stay in the property thread; only decisions appear here.');
 return header('YOUR OPERATIONS AT A GLANCE','Good work starts with a clear plan.','Today’s turnovers, team assignments, and business pulse.',addJobButton())+`<div class="stats"><div class="stat"><div class="stat-label">TODAY’S TURNOVERS</div><div class="stat-number">${todays.length}</div><div class="stat-help">${open.length} jobs still in progress overall</div></div><div class="stat"><div class="stat-label">PROPERTIES</div><div class="stat-number">${db.properties.length}</div><div class="stat-help">Across your client portfolio</div></div><div class="stat"><div class="stat-label">INVOICES TO COLLECT</div><div class="stat-number">${money(outstanding)}</div><div class="stat-help">Completed jobs marked unpaid</div></div><div class="stat"><div class="stat-label">LOW STOCK ITEMS</div><div class="stat-number">${low.length}</div><div class="stat-help">Supplies at or below reorder point</div></div></div><div class="section-grid"><div>${card('Today’s turnovers','Your team’s plan for the day',todayRows,`<button class="outline-btn" data-page="schedule">Full schedule ↗</button>`)}${card('This week','Upcoming work and assignments',week.length?week.slice(0,5).map(miniJob).join(''):empty('No jobs on the calendar','Add a turnover or import an iCal calendar.'),`<button class="outline-btn" data-page="schedule">Open calendar</button>`)}</div><div>${card('Only needs your attention','The assistant routes exceptions here for review',`<div class="card-body">${updates}</div>`,`<button class="outline-btn" data-page="messages">Open unit inbox</button>`)}${card('Quick actions','Keep operations moving',`<div class="card-body quick-actions"><button class="soft-btn" data-page="properties">＋ Add a property</button><button class="soft-btn" data-page="team">＋ Add a team member</button><button class="soft-btn" data-page="inventory">＋ Log supplies</button><button class="soft-btn" data-page="finance">＋ Record an expense</button></div>`)}</div></div>`;
}
function jobForm(){return `<form id="jobForm"><div class="form-grid"><div class="field"><label>PROPERTY *</label><select name="propertyId" required>${propsOptions()}</select></div><div class="field"><label>TURNOVER DATE *</label><input name="date" type="date" value="${today()}" required></div><div class="field"><label>START WINDOW</label><input name="time" placeholder="e.g. 11:00 AM – 4:00 PM"></div><div class="field"><label>LEAD CLEANER</label><select name="cleanerId">${teamOptions()}</select></div><div class="field"><label>OWNER PRICE ($)</label><input name="fee" type="number" min="0" step="0.01" placeholder="0.00"></div><div class="field"><label>CLEANER PAY ($)</label><input name="pay" type="number" min="0" step="0.01" placeholder="0.00"></div><div class="field full"><label>JOB NOTE</label><textarea name="note" placeholder="Guest checkout, laundry, restocking, access notes..."></textarea></div></div><div class="form-actions"><button type="button" class="outline-btn" data-action="cancel-form">Cancel</button><button class="solid-btn">Create turnover</button></div></form>`;}
function schedule(){const y=calDate.getFullYear(),m=calDate.getMonth(),first=new Date(y,m,1),last=new Date(y,m+1,0),offset=first.getDay(),days=last.getDate(),cells=Math.ceil((offset+days)/7)*7;let daysHtml='';for(let i=0;i<cells;i++){const day=i-offset+1,d=new Date(y,m,day),valid=day>0&&day<=days,keyDate=localKey(d),dayJobs=db.jobs.filter(j=>j.date===keyDate);daysHtml+=`<div class="calendar-day ${valid?'':'outside'} ${keyDate===today()?'today':''}"><span class="day-number">${valid?day:''}</span>${dayJobs.slice(0,2).map(j=>`<span class="cal-job ${j.status==='completed'?'':'tight'}" data-job="${safe(j.id)}">${safe(propName(j.propertyId))}</span>`).join('')}${dayJobs.length>2?`<span class="muted">+${dayJobs.length-2} more</span>`:''}</div>`;}
 const monthTitle=calDate.toLocaleDateString('en-US',{month:'long',year:'numeric'});const jobs=[...db.jobs].sort((a,b)=>a.date.localeCompare(b.date));
 return header('SCHEDULING & DISPATCH','Your schedule, in sync.','Plan turns, assign the right cleaner, and keep every handoff attached to the job.',`${addJobButton()} <button class="outline-btn" data-action="import-ical">⇧ Import iCal</button>`)+`<div id="jobFormSlot" hidden>${card('Schedule a turnover','Choose a property and assign the lead cleaner.',`<div class="card-body">${jobForm()}</div>`)}</div>`+card('Turnover calendar','Select a job to open its checklist, inspection, and job notes.',`<div class="card-body"><div class="month-controls"><button data-action="month-prev">‹</button><strong>${monthTitle}</strong><button data-action="month-next">›</button></div><div class="week-grid">${['SUN','MON','TUE','WED','THU','FRI','SAT'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar-grid">${daysHtml}</div></div>`)+card('All turnovers','Cleaner assignment, job progress, and owner price',jobs.length?`<div class="scroll-table"><table class="ops-table"><thead><tr><th>PROPERTY</th><th>DATE</th><th>ASSIGNED CLEANER</th><th>STATUS</th><th>OWNER PRICE</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td><strong>${safe(propName(j.propertyId))}</strong><div class="job-sub">${safe(j.time||'No time set')}</div></td><td>${dateText(j.date)}</td><td>${safe(teamName(j.cleanerId))}</td><td>${statusBadge(j.status)}</td><td class="money">${money(j.fee)}</td><td><button class="tiny-btn" data-job="${safe(j.id)}">Open job</button></td></tr>`).join('')}</tbody></table></div>`:empty('No turnovers scheduled','Create a job manually or import an iCal file for one of your properties.',addJobButton()));}
function propertyPage(){const cards=db.properties.map(p=>`<article class="property-card"><div class="property-top"><span class="property-icon">⌂</span><button class="tiny-btn danger" data-delete-property="${safe(p.id)}">Remove</button></div><h3>${safe(p.name)}</h3><div class="muted">${safe(p.address)}${p.unit?` · ${safe(p.unit)}`:''}</div><div class="detail-line"><b>Client</b> &nbsp;${safe(p.client||'Owner not set')}</div><div class="detail-line"><b>Standard price</b> &nbsp;${money(p.rate)} &nbsp; · &nbsp; <b>Cleaner pay</b> &nbsp;${money(p.pay)}</div><div class="detail-line"><b>Access</b> &nbsp;${safe(p.access||'Add access instructions')}</div><div class="detail-line"><b>Linens</b> &nbsp;${safe(p.linen||'Not specified')}</div><ul class="detail-list">${(p.checklist||[]).slice(0,5).map(c=>`<li>✓ ${safe(c.text)}</li>`).join('')}</ul></article>`).join('');
 const form=`<form id="propertyForm"><div class="form-grid"><div class="field"><label>PROPERTY NAME *</label><input name="name" required placeholder="Oceanview Bungalow"></div><div class="field"><label>OWNER / CLIENT</label><input name="client" placeholder="Client name"></div><div class="field full"><label>ADDRESS *</label><input name="address" required placeholder="Street, city, ZIP"></div><div class="field"><label>UNIT / SUITE</label><input name="unit" placeholder="Unit number"></div><div class="field"><label>OWNER PRICE PER TURN ($)</label><input name="rate" type="number" min="0" step=".01" placeholder="175"></div><div class="field"><label>STANDARD CLEANER PAY ($)</label><input name="pay" type="number" min="0" step=".01" placeholder="95"></div><div class="field"><label>ACCESS / PARKING NOTES</label><input name="access" placeholder="Lockbox, parking, gate..." /></div><div class="field"><label>LINEN SETUP</label><input name="linen" placeholder="Queen x2, bath sets x4..."></div><div class="field full"><label>PROPERTY CHECKLIST (one task per line)</label><textarea name="checklist">Strip used linens\nClean kitchen and appliances\nSanitize bathrooms\nVacuum and mop floors\nRestock guest essentials\nTake final photos</textarea></div></div><div class="form-actions"><button class="solid-btn">Save property</button></div></form>`;
 return header('PROPERTY DETAILS','Every place has its own playbook.','Keep owner details, access notes, linen setup, and room-by-room standards together.',`<button class="solid-btn" data-action="show-property-form">＋ Add property</button>`)+`<div id="propertyFormSlot" hidden>${card('Add a property','Details stay with the property and can be added to every turnover.',`<div class="card-body">${form}</div>`)}</div>`+(cards?`<div class="property-grid">${cards}</div>`:card('Your property portfolio','Start with one listing; instructions and checklist are stored with it.',empty('No properties added yet','Add a property to schedule and assign turnovers.',`<button class="solid-btn" data-action="show-property-form">＋ Add your first property</button>`)));
}
function teamPage(){const crew=db.team.map(t=>`<article class="crew-card"><div class="property-top"><span class="avatar-crew">${safe(t.name.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase())}</span><button class="tiny-btn danger" data-delete-team="${safe(t.id)}">Remove</button></div><h3>${safe(t.name)}</h3><div class="muted">${safe(t.role||'Cleaner')} · ${safe(t.phone||'No phone added')}</div><div class="detail-line"><b>Pay rate</b> &nbsp;${money(t.rate)} per turnover</div><div class="detail-line"><b>Assigned upcoming jobs</b> &nbsp;${db.jobs.filter(j=>j.cleanerId===t.id&&j.status!=='completed').length}</div></article>`).join('');
 const form=`<form id="teamForm"><div class="form-grid"><div class="field"><label>NAME *</label><input name="name" required placeholder="Cleaner name"></div><div class="field"><label>ROLE</label><select name="role"><option>Cleaner</option><option>Lead cleaner</option><option>Inspector</option><option>Manager</option></select></div><div class="field"><label>PHONE</label><input name="phone" type="tel" placeholder="(619) 555-0100"></div><div class="field"><label>DEFAULT PAY PER TURN ($)</label><input name="rate" type="number" min="0" step=".01" placeholder="95"></div></div><div class="form-actions"><button class="solid-btn">Add team member</button></div></form>`;
 return header('PEOPLE & PERMISSIONS','A reliable team, on the same page.','Add cleaners, inspectors, and helpers; assign jobs and calculate pay from completed work.',`<button class="solid-btn" data-action="show-team-form">＋ Add team member</button>`)+`<div id="teamFormSlot" hidden>${card('Add a team member','Pay rates are used for the job payroll estimate.',`<div class="card-body">${form}</div>`)}</div>`+(crew?`<div class="crew-grid">${crew}</div>`:card('Build your crew','Set each person up once, then assign them to turnovers.',empty('No team members yet','Add the people who clean and inspect your rentals.',`<button class="solid-btn" data-action="show-team-form">＋ Add first team member</button>`)));
}
function inventoryPage(){const rows=db.inventory.map(i=>`<tr><td><strong>${safe(i.name)}</strong><div class="job-sub">${safe(i.propertyId?propName(i.propertyId):'Shared supply')}</div></td><td>${safe(i.category||'Supply')}</td><td><span class="money">${Number(i.qty)||0} ${safe(i.unit||'')}</span><div class="stock-track"><i class="${Number(i.qty)<=Number(i.min)?'low':''}" style="width:${Math.max(5,Math.min(100,Number(i.qty)/(Math.max(1,Number(i.min)*2))*100))}%"></i></div></td><td>${Number(i.min)||0} ${safe(i.unit||'')}</td><td>${Number(i.qty)<=Number(i.min)?'<span class="badge badge-due">Reorder</span>':'<span class="badge badge-paid">In stock</span>'}</td><td><button class="tiny-btn" data-stock="${safe(i.id)}" data-delta="-1">−</button> <button class="tiny-btn" data-stock="${safe(i.id)}" data-delta="1">＋</button></td></tr>`).join('');
 const form=`<form id="inventoryForm"><div class="form-grid"><div class="field"><label>ITEM NAME *</label><input name="name" required placeholder="Bath towels"></div><div class="field"><label>CATEGORY</label><select name="category"><option>Linen</option><option>Cleaning supply</option><option>Amenity</option><option>Equipment</option></select></div><div class="field"><label>PROPERTY</label><select name="propertyId">${'<option value="">Shared / team stock</option>'+db.properties.map(p=>`<option value="${safe(p.id)}">${safe(p.name)}</option>`).join('')}</select></div><div class="field"><label>CURRENT QUANTITY</label><input name="qty" type="number" min="0" value="1"></div><div class="field"><label>REORDER AT</label><input name="min" type="number" min="0" value="2"></div><div class="field"><label>UNIT</label><input name="unit" placeholder="each, pack, bottle"></div></div><div class="form-actions"><button class="solid-btn">Add inventory item</button></div></form>`;
 return header('SUPPLIES & LINENS','Know what’s ready before you arrive.','Track amenities, linens, and cleaning supplies by property. Log usage after each turn.',`<button class="solid-btn" data-action="show-inventory-form">＋ Add item</button>`)+`<div id="inventoryFormSlot" hidden>${card('Add an inventory item','Set a reorder point and keep low stock visible.',`<div class="card-body">${form}</div>`)}</div>`+card('Inventory levels','Low stock is flagged so you can restock before the next check-in.',rows?`<div class="scroll-table"><table class="ops-table"><thead><tr><th>ITEM</th><th>CATEGORY</th><th>ON HAND</th><th>REORDER AT</th><th>STATUS</th><th>ADJUST</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('No inventory recorded','Add your first supply or linen item.'));
}
function financePage(){const completed=db.jobs.filter(j=>j.status==='completed'),unpaid=completed.filter(j=>j.invoiceStatus!=='paid'),invoiced=completed.reduce((s,j)=>s+(Number(j.fee)||0),0),paid=completed.filter(j=>j.invoiceStatus==='paid').reduce((s,j)=>s+(Number(j.fee)||0),0),payroll=completed.reduce((s,j)=>s+(Number(j.pay)||0),0),expense=db.expenses.reduce((s,x)=>s+(Number(x.amount)||0),0),profit=paid-payroll-expense;
 const invoiceRows=completed.map(j=>`<tr><td><strong>${safe(propName(j.propertyId))}</strong><div class="job-sub">Turnover · ${dateText(j.date)}</div></td><td>${safe(db.properties.find(p=>p.id===j.propertyId)?.client||'Owner')}</td><td class="money">${money(j.fee)}</td><td>${j.invoiceStatus==='paid'?'<span class="badge badge-paid">Paid</span>':'<span class="badge badge-due">Draft / unpaid</span>'}</td><td>${j.invoiceStatus==='paid'?`<button class="tiny-btn" data-invoice="${safe(j.id)}" data-pay="unpaid">Mark unpaid</button>`:`<button class="tiny-btn" data-invoice="${safe(j.id)}" data-pay="paid">Mark paid</button>`}</td></tr>`).join('');
 const expenseRows=db.expenses.map(x=>`<tr><td><strong>${safe(x.name)}</strong><div class="job-sub">${dateText(x.date)}</div></td><td>${safe(x.category)}</td><td>${safe(x.note||'—')}</td><td class="money negative">−${money(x.amount)}</td></tr>`).join('');
 const form=`<form id="expenseForm"><div class="form-grid"><div class="field"><label>EXPENSE *</label><input name="name" required placeholder="Linen restock"></div><div class="field"><label>AMOUNT ($) *</label><input name="amount" type="number" min="0" step=".01" required></div><div class="field"><label>CATEGORY</label><select name="category"><option>Supplies</option><option>Laundry</option><option>Travel</option><option>Equipment</option><option>Other</option></select></div><div class="field"><label>DATE</label><input name="date" type="date" value="${today()}"></div><div class="field full"><label>NOTE</label><input name="note" placeholder="Optional details"></div></div><div class="form-actions"><button class="solid-btn">Save expense</button></div></form>`;
 const payrollRows=completed.map(j=>`<tr><td><strong>${safe(teamName(j.cleanerId))}</strong></td><td>${safe(propName(j.propertyId))}</td><td>${dateText(j.date)}</td><td class="money">${money(j.pay)}</td><td><span class="badge badge-completed">Completed</span></td></tr>`).join('');
 return header('MONEY & MARGINS','See where your work is paying off.','Completed turnovers create owner invoices and cleaner pay entries automatically.',`<button class="outline-btn" data-action="export-payroll">⇩ Payroll CSV</button> <button class="solid-btn" data-action="show-expense-form">＋ Record expense</button>`)+`<div class="stats"><div class="stat"><div class="stat-label">INVOICED</div><div class="stat-number">${money(invoiced)}</div><div class="stat-help">${completed.length} completed turnovers</div></div><div class="stat"><div class="stat-label">COLLECTED</div><div class="stat-number">${money(paid)}</div><div class="stat-help">Mark invoice paid when received</div></div><div class="stat"><div class="stat-label">CLEANER PAY</div><div class="stat-number">${money(payroll)}</div><div class="stat-help">Based on completed job pay rates</div></div><div class="stat"><div class="stat-label">EST. OPERATING PROFIT</div><div class="stat-number">${money(profit)}</div><div class="stat-help">Collected − cleaner pay − expenses</div></div></div><div id="expenseFormSlot" hidden>${card('Record an expense','Track purchases and operating costs.',`<div class="card-body">${form}</div>`)}</div>${card('Owner invoices','Mark each completed clean paid when the owner settles.',invoiceRows?`<div class="invoice-summary"><div>Outstanding<strong>${money(invoiced-paid)}</strong></div><div>Collected<strong>${money(paid)}</strong></div></div><div class="scroll-table"><table class="ops-table"><thead><tr><th>INVOICE</th><th>CLIENT</th><th>AMOUNT</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${invoiceRows}</tbody></table></div>`:empty('No invoices yet','Complete a turnover to create an owner invoice.'))}${card('Cleaner payroll','A transparent record of completed-job pay.',payrollRows?`<div class="scroll-table"><table class="ops-table"><thead><tr><th>CLEANER</th><th>PROPERTY</th><th>COMPLETED</th><th>PAY</th><th>STATUS</th></tr></thead><tbody>${payrollRows}</tbody></table></div>`:empty('No completed jobs','Completed turnovers will show cleaner pay here.'))}${card('Operating expenses','Keep supply runs and business costs in one place.',expenseRows?`<div class="scroll-table"><table class="ops-table"><thead><tr><th>EXPENSE</th><th>CATEGORY</th><th>NOTE</th><th>AMOUNT</th></tr></thead><tbody>${expenseRows}</tbody></table></div>`:empty('No expenses logged','Record expenses to make your profit estimate more useful.'))}`;
}
function makeConversationMessage({propertyId,text,sender,senderRole,isAI=false,needsOwner=false,reason='',resolved=false}){return {id:id(),isConversation:true,propertyId,text,sender,senderRole,isAI,needsOwner,reason,resolved,date:today(),createdAt:new Date().toISOString()};}
function previewAssistantReply(text,property,role){
 const q=text.toLowerCase();
 if(/\b(locked out|can't get in|cannot get in|locked outside|no access|door won't|keypad.*(fail|broken)|lock.*(fail|broken)|leak|flood|fire|smoke|injur|unsafe|emergency|broken window|burst pipe)\b/.test(q))return {reason:'Urgent access / safety / damage',urgent:true,reply:`I’m flagging this for the owner now. If anyone is in immediate danger, contact emergency services. I won’t guess about access or repairs.`};
 if(/\b(price|cost|charge|refund|complaint|unhappy|cancel|cancellation|extra clean|additional clean|reschedul|change the date|move the date|different day|booking|schedule|availability|friday|saturday|sunday|monday|tuesday|wednesday|thursday)\b/.test(q))return {reason:'Schedule, service, or money decision',reply:`I’ve sent this request to the owner for review. I won’t confirm a date, service, or price until they approve it.`};
 if(/\b(code|lockbox|key|entry|access|gate|parking)\b/.test(q)){
   if(role!=='cleaner')return {reason:'Access details are crew-only',reply:`I can’t share crew-only entry or access instructions in this conversation. I’ve routed the request to the owner.`};
   if(property.access)return {reply:`For ${property.name}: ${property.access}`};
   return {reason:'Missing access instructions',reply:`I don’t have approved access instructions for ${property.name}. I’ve asked the owner to add them.`};
 }
 if(/\b(linen|linens|towel|towels|sheet|sheets|laundry|bed)\b/.test(q)){
   if(property.linen)return {reply:`Linen setup for ${property.name}: ${property.linen}`};
   return {reason:'Missing linen setup',reply:`I don’t have linen details saved for ${property.name}. I’ve asked the owner to add them.`};
 }
 if(/\b(checklist|what should i clean|what do i need to do|cleaning tasks|tasks for this turn)\b/.test(q)){
   const tasks=(property.checklist||[]).map(x=>x.text).filter(Boolean);
   if(tasks.length)return {reply:`Here’s the saved checklist for ${property.name}:\n${tasks.map((x,i)=>`${i+1}. ${x}`).join('\n')}`};
   return {reason:'Missing property checklist',reply:`There isn’t a checklist saved for ${property.name} yet. I’ve asked the owner to add one.`};
 }
 if(/\b(supply|supplies|toilet paper|toiletries|soap|amenities|restock|out of|running low)\b/.test(q)){
   const item=db.inventory.find(x=>(!x.propertyId||x.propertyId===property.id)&&q.includes(x.name.toLowerCase()));
   if(item&&Number(item.qty)>Number(item.min))return {reply:`${item.name}: ${item.qty} ${item.unit||'on hand'} for ${item.propertyId?property.name:'shared stock'}.`};
   return {reason:'Supply request',reply:`I’ve logged this as a supply request for ${property.name} and sent it to the owner to review.`};
 }
 if(/\b(status|finished|complete|completed|started|arrival|arrived|turnover)\b/.test(q)){
   const job=db.jobs.filter(j=>j.propertyId===property.id).sort((a,b)=>b.date.localeCompare(a.date))[0];
   if(job)return {reply:`Latest turnover for ${property.name}: ${job.status.replace('_',' ')} on ${dateText(job.date)}${job.time?` (${job.time})`:''}.`};
 }
 return {reason:'Needs a human answer',reply:`I don’t have enough approved information to answer that reliably. I’ve sent it to the owner, who can reply in this unit thread.`};
}
function sendUnitMessage(text,role=commRole){const property=db.properties.find(p=>p.id===activeCommPropertyId);if(!property||!text.trim())return;const sender=role==='cleaner'?'Cleaner preview':'Client / owner preview';db.messages.push(makeConversationMessage({propertyId:property.id,text:text.trim(),sender,senderRole:role}));const result=db.aiSettings.autoFaq?previewAssistantReply(text.trim(),property,role):{reason:'Owner approval mode',reply:`I’ve passed your message to the owner. They’ll reply here.`};if(result.reason){const original=db.messages.at(-1);original.needsOwner=true;original.reason=result.reason;original.urgent=!!result.urgent;}db.messages.push(makeConversationMessage({propertyId:property.id,text:result.reply,sender:'CairBnB assistant · preview',senderRole:'assistant',isAI:true}));saveDB();render();setTimeout(()=>{const area=document.getElementById('unitMessage');area?.focus();},20);}
function resolveOwnerReview(messageId,decision){const m=db.messages.find(x=>x.id===messageId&&x.isConversation);if(!m)return;m.resolved=true;m.ownerDecision=decision;const result=decision==='approve'?`The owner approved this request and will confirm the final details here.`:decision==='decline'?`The owner reviewed this request and can’t approve it as requested. They’ll follow up with another option.`:`The owner has seen this and will follow up here.`;db.messages.push(makeConversationMessage({propertyId:m.propertyId,text:result,sender:'CairBnB assistant · owner-reviewed',senderRole:'assistant',isAI:true}));saveDB();render();showToast(decision==='approve'?'Approved and added to the conversation.':'Owner review updated.');}
function messagesPage(){
 if(!db.properties.length)return header('AI UNIT CONCIERGE','One conversation, anchored to every unit.','Owners and cleaners share the right thread. CairBnB handles routine questions and brings you the exceptions.',`<span class="badge">Preview mode</span>`)+card('Set up your first unit','Add a property to start a property-specific conversation.',empty('No units to connect yet','Property details give the assistant its approved source of truth.',`<button class="solid-btn" data-page="properties">＋ Add a property</button>`));
 if(!db.properties.some(p=>p.id===activeCommPropertyId))activeCommPropertyId=db.properties[0].id;
 const property=db.properties.find(p=>p.id===activeCommPropertyId);
 const conversations=db.messages.filter(m=>m.isConversation&&m.propertyId);
 const escalations=conversations.filter(m=>m.needsOwner&&!m.resolved);
 const inbox=db.properties.map(p=>{const rows=conversations.filter(m=>m.propertyId===p.id),last=rows.at(-1),pending=rows.filter(m=>m.needsOwner&&!m.resolved).length;return `<button class="inbox-unit ${p.id===activeCommPropertyId?'active':''}" data-thread="${safe(p.id)}"><span class="inbox-unit-icon">⌂</span><span class="inbox-unit-copy"><b>${safe(p.name)}</b><small>${safe(last?.text||'Start a unit conversation')}</small></span>${pending?`<i class="inbox-unread">${pending}</i>`:''}</button>`;}).join('');
 const thread=conversations.filter(m=>m.propertyId===property.id);
 const bubbles=thread.map(m=>`<div class="chat-message ${m.isAI?'assistant-message':m.senderRole==='owner'?'owner-message':'person-message'}"><div class="message-byline"><span>${safe(m.isAI?'CairBnB assistant':m.sender||'Team member')}</span><time>${new Date(m.createdAt||m.date||Date.now()).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}</time>${m.needsOwner&&!m.resolved?'<em>OWNER REVIEW</em>':''}${m.resolved?'<em class="resolved-tag">HANDLED</em>':''}</div><div class="message-text">${safe(m.text)}</div>${m.needsOwner&&!m.resolved?`<div class="message-review"><button data-escalation="${safe(m.id)}" data-decision="approve">Approve & reply</button><button data-escalation="${safe(m.id)}" data-decision="decline">Decline request</button><button data-escalation="${safe(m.id)}" data-decision="dismiss">Mark handled</button></div>`:''}</div>`).join('')||`<div class="thread-welcome"><span class="welcome-mark">✳</span><h3>Good communication, without the noise.</h3><p>Start a conversation for <b>${safe(property.name)}</b>. Routine property questions get an instant answer. Schedule changes, complaints, damage, and uncertain requests go to the owner.</p><div class="prompt-chips"><button data-prompt="Where should I find the linens?">Ask about linens</button><button data-prompt="What should I focus on for this turnover?">Ask about the checklist</button><button data-prompt="We need an extra cleaning this Friday.">Request a schedule change</button></div></div>`;
 const openOwnerCount=escalations.length;
 return header('AI UNIT CONCIERGE','One conversation, anchored to every unit.','Owners and cleaners share the right thread. CairBnB handles routine questions and brings you the exceptions.',`<span class="ai-live-pill"><i></i> OWNER CONTROLLED</span>`)+`<div class="concierge-note"><span class="concierge-spark">✳</span><div><b>Less back-and-forth. You keep the final say.</b><small>Routine details can be answered from your property records. Schedule, price, damage, complaints, and uncertain requests are routed to your review queue.</small><small class="preview-disclosure">This preview uses local rules, not a live AI service. Shared chat, real AI replies, SMS, and scheduled digests need a connected backend.</small></div><span class="preview-badge">LOCAL PREVIEW</span></div><div class="unit-inbox-shell"><aside class="inbox-rail"><div class="inbox-rail-head"><div><span>PROPERTY THREADS</span><small>${db.properties.length} unit${db.properties.length===1?'':'s'}</small></div><button title="Refresh inbox" data-action="refresh-inbox">↻</button></div><div class="inbox-unit-list">${inbox}</div><details class="owner-controls" open><summary><span class="control-orbit">✳</span><span><b>Owner controls</b><small>Set the assistant’s boundaries</small></span><span class="summary-caret">⌄</span></summary><div class="control-row"><div><b>Answer routine FAQs</b><small>Use approved unit details only</small></div><label class="switch"><input type="checkbox" data-setting="autoFaq" ${db.aiSettings.autoFaq?'checked':''}><span></span></label></div><label class="control-select-label">DIGEST PREFERENCE<select data-setting="digest"><option value="twice_daily" ${db.aiSettings.digest==='twice_daily'?'selected':''}>Twice a day</option><option value="daily" ${db.aiSettings.digest==='daily'?'selected':''}>Once a day</option><option value="urgent_only" ${db.aiSettings.digest==='urgent_only'?'selected':''}>Urgent only</option></select></label><div class="owner-guardrail"><span>↗</span><div><b>Always ask you first</b><small>Changes, rates, complaints, damage, access failures</small></div></div><div class="escalation-total"><span>Waiting for you</span><b>${openOwnerCount}</b></div></details></aside><section class="unit-chat"><div class="unit-chat-head"><div class="unit-title-mark">⌂</div><div class="unit-title-copy"><b>${safe(property.name)}</b><small>${safe(property.address)}${property.unit?` · ${safe(property.unit)}`:''}</small></div><label class="persona-select">PREVIEW AS<select id="commRole"><option value="cleaner" ${commRole==='cleaner'?'selected':''}>Cleaner</option><option value="client" ${commRole==='client'?'selected':''}>Client / owner</option></select></label><span class="role-dot">DEMO</span></div><div class="thread-scroll" id="threadScroll">${bubbles}</div><form id="unitComposer" class="unit-composer"><div class="composer-top"><span>Message <b>${commRole==='cleaner'?'as the cleaner':'as the client / owner'}</b></span><span>↵ to send</span></div><div class="composer-input-wrap"><textarea id="unitMessage" name="text" rows="2" maxlength="1200" placeholder="Ask about the unit, share an update, or report an issue…" required></textarea><button class="composer-send" aria-label="Send message">↑</button></div><div class="composer-foot"><span><i></i> Assistant replies use saved property details</span><span>Local preview · no text is sent externally</span></div></form></section></div><section class="owner-queue ${openOwnerCount?'has-items':''}"><div class="owner-queue-title"><span class="queue-icon">↗</span><div><b>Owner review queue</b><small>${openOwnerCount?`${openOwnerCount} item${openOwnerCount===1?'':'s'} need your decision`:'You’re clear. The assistant will bring you exceptions here.'}</small></div><span class="queue-count">${openOwnerCount}</span></div>${openOwnerCount?escalations.map(m=>`<div class="queue-item"><span class="queue-alert">!</span><div><b>${safe(propName(m.propertyId))} · ${safe(m.reason||'Owner review')}</b><p>${safe(m.text)}</p><small>From ${safe(m.sender||'Unit thread')} · ${dateText(m.date,{month:'short',day:'numeric'})}</small></div><button data-thread="${safe(m.propertyId)}" class="queue-open">Open thread ↗</button></div>`).join(''):''}</section>`;
}
let opsRevealObserver;
function revealOps(){if(opsRevealObserver){opsRevealObserver.disconnect();opsRevealObserver=null;}const targets=document.querySelectorAll('#opsContent .page-head,#opsContent .stats,#opsContent .card,#opsContent .property-card,#opsContent .crew-card');if(!('IntersectionObserver'in window)){targets.forEach(x=>x.classList.add('revealed'));return;}if(!opsRevealObserver)opsRevealObserver=new IntersectionObserver(items=>items.forEach(i=>{if(i.isIntersecting){i.target.classList.add('revealed');opsRevealObserver.unobserve(i.target);}}),{threshold:.08});targets.forEach((el,i)=>{el.classList.add('reveal');el.style.transitionDelay=`${Math.min(i,5)*45}ms`;opsRevealObserver.observe(el);});}
function render(){document.getElementById('todayLabel').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});document.getElementById('scheduleCount').textContent=db.jobs.filter(j=>j.status!=='completed').length;const titles={overview:'Overview',schedule:'Schedule',properties:'Properties',team:'Team',inventory:'Inventory',finance:'Invoices & payroll',messages:'Unit inbox'};document.getElementById('crumb').textContent=titles[page]||'Overview';document.querySelectorAll('.ops-link').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const pages={overview,schedule,properties:propertyPage,team:teamPage,inventory:inventoryPage,finance:financePage,messages:messagesPage};document.getElementById('opsContent').innerHTML=(pages[page]||overview)();const pending=db.messages.filter(m=>m.isConversation&&m.needsOwner&&!m.resolved).length;document.getElementById('escalationCount').textContent=pending;revealOps();const scroller=document.getElementById('threadScroll');if(scroller)scroller.scrollTop=scroller.scrollHeight;}
function setPage(p){page=p;render();window.scrollTo(0,0);}
function showModal(html){document.getElementById('opsModal').innerHTML=html;document.getElementById('opsBackdrop').classList.add('open');}
function closeModal(){document.getElementById('opsBackdrop').classList.remove('open');detailJobId=null;}
function openJob(jid){const j=db.jobs.find(x=>x.id===jid);if(!j)return;detailJobId=jid;const p=db.properties.find(x=>x.id===j.propertyId);const checks=j.checklist||[];showModal(`<button class="modal-close" data-action="close-modal">×</button><div class="eyebrow">TURNOVER · ${dateText(j.date)}</div><h2>${safe(propName(j.propertyId))}</h2><div class="modal-desc">${safe(p?.address||'')} · ${safe(j.time||'Flexible start')} · ${statusBadge(j.status)}</div><div class="form-grid"><div class="field"><label>LEAD CLEANER</label><select id="jobCleaner">${teamOptions(j.cleanerId)}</select></div><div class="field"><label>STATUS</label><select id="jobStatus"><option value="scheduled" ${j.status==='scheduled'?'selected':''}>Scheduled</option><option value="in_progress" ${j.status==='in_progress'?'selected':''}>In progress</option><option value="completed" ${j.status==='completed'?'selected':''}>Completed</option></select></div></div><div class="modal-label" style="font-size:9px;font-weight:700;color:#7e8981;margin:15px 0 7px">PROPERTY CHECKLIST & INSPECTION</div>${checks.length?checks.map((c,i)=>`<label class="checklist-work"><input type="checkbox" data-check="${i}" ${c.done?'checked':''}> ${safe(c.text)}</label>`).join(''):empty('No checklist set','Add checklist tasks in the property settings.') }<div class="field" style="margin-top:12px"><label>DAMAGE / MAINTENANCE NOTE</label><textarea id="jobDamage" placeholder="Describe damage, missing items, or maintenance issue...">${safe(j.damage||'')}</textarea></div><div class="field" style="margin-top:10px"><label>PHOTO PROOF / DAMAGE PHOTOS</label><input id="jobPhotos" type="file" accept="image/*" multiple><div class="photo-grid">${(j.photos||[]).map(src=>`<img src="${safe(src)}" alt="Turnover photo" loading="lazy">`).join('')}</div></div><div class="form-grid" style="margin-top:10px"><div class="field"><label>OWNER PRICE ($)</label><input id="jobFee" type="number" min="0" step=".01" value="${Number(j.fee)||0}"></div><div class="field"><label>CLEANER PAY ($)</label><input id="jobPay" type="number" min="0" step=".01" value="${Number(j.pay)||0}"></div></div><div class="modal-footer"><button class="outline-btn" data-action="close-modal">Close</button><button class="solid-btn" data-action="save-job-detail">Save job</button></div>`);}
function addJobFromForm(form){const d=new FormData(form), property=db.properties.find(p=>p.id===d.get('propertyId'));if(!property){showToast('Add a property before creating a turnover.');return;}const job={id:id(),propertyId:property.id,date:d.get('date'),time:d.get('time'),cleanerId:d.get('cleanerId'),fee:Number(d.get('fee'))||Number(property.rate)||0,pay:Number(d.get('pay'))||Number(property.pay)||0,note:d.get('note'),status:'scheduled',invoiceStatus:'unpaid',checklist:(property.checklist||[]).map(c=>({...c,done:false})),photos:[],damage:''};db.jobs.push(job);if(job.note)db.messages.push({id:id(),text:`${propName(job.propertyId)} · ${job.note}`,date:today(),author:'Manager',jobId:job.id});saveDB();render();showToast('Turnover added to schedule.');}
function icsDate(s){if(!s)return '';const m=s.match(/\d{4}(\d{2})(\d{2})/);return m?`${s.slice(0,4)}-${m[1]}-${m[2]}`:'';}
function importICS(text,propertyId){if(typeof text!=='string'||text.length>10*1024*1024)throw new Error('Calendar file is larger than the 10 MB limit.');const blocks=text.match(/BEGIN:VEVENT[\s\S]*?END:VEVENT/g)||[];if(blocks.length>1000)throw new Error('Calendar file contains more than 1,000 events.');let count=0;for(const b of blocks){const summary=(b.match(/^SUMMARY(?:;[^:]*)?:(.*)$/mi)||[])[1]||'Rental checkout';const start=(b.match(/^DTSTART(?:;[^:]*)?:(.*)$/mi)||[])[1]||'';const date=icsDate(start.trim());if(!date)continue;const p=db.properties.find(x=>x.id===propertyId);if(!p)break;const exists=db.jobs.some(j=>j.propertyId===p.id&&j.date===date&&j.icalSummary===summary);if(exists)continue;db.jobs.push({id:id(),propertyId:p.id,date,time:'Turnover after checkout',cleanerId:'',fee:Number(p.rate)||0,pay:Number(p.pay)||0,note:`Imported calendar event: ${summary}`,icalSummary:summary,status:'scheduled',invoiceStatus:'unpaid',checklist:(p.checklist||[]).map(c=>({...c,done:false})),photos:[],damage:''});count++;}saveDB();setPage('schedule');showToast(`${count} calendar event${count===1?'':'s'} added as turnover jobs.`);}
async function imageToSmallData(file){return new Promise((resolve,reject)=>{if(!file||!file.type.startsWith('image/')||file.size>10*1024*1024){reject(new Error('Choose an image under 10 MB.'));return;}const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{try{if(img.width>10000||img.height>10000||img.width*img.height>50000000)throw new Error('That image is too large to process.');const scale=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)throw new Error('Image processing is unavailable.');ctx.drawImage(img,0,0,canvas.width,canvas.height);let result=canvas.toDataURL('image/jpeg',.62);if(result.length>300000)result=canvas.toDataURL('image/jpeg',.42);if(result.length>300000)throw new Error('Compressed photo is still too large.');resolve(result);}catch(error){reject(error);}finally{URL.revokeObjectURL(url);}};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Could not read that image.'));};img.src=url;});}
function csvSafeCell(value){let text=String(value??'');if(/^[\s\u0000-\u001f]*[=+\-@]/.test(text))text="'"+text;return `"${text.replace(/"/g,'""')}"`;}
function exportPayroll(){const done=db.jobs.filter(j=>j.status==='completed');const rows=[['Cleaner','Property','Date','Pay'],...done.map(j=>[teamName(j.cleanerId),propName(j.propertyId),j.date,Number(j.pay)||0])];const csv=rows.map(r=>r.map(csvSafeCell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='cairbnb-payroll.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function onAction(action){if(action==='refresh-inbox'){render();showToast('Unit inbox refreshed.');}if(action==='add-job'){setPage('schedule');setTimeout(()=>document.getElementById('jobFormSlot')?.scrollIntoView({behavior:'smooth',block:'center'}),20);}if(action==='show-property-form'){const x=document.getElementById('propertyFormSlot');if(x){x.hidden=false;x.scrollIntoView({behavior:'smooth',block:'center'});}}if(action==='show-team-form'){const x=document.getElementById('teamFormSlot');if(x){x.hidden=false;x.scrollIntoView({behavior:'smooth',block:'center'});}}if(action==='show-inventory-form'){const x=document.getElementById('inventoryFormSlot');if(x){x.hidden=false;x.scrollIntoView({behavior:'smooth',block:'center'});}}if(action==='show-expense-form'){const x=document.getElementById('expenseFormSlot');if(x){x.hidden=false;x.scrollIntoView({behavior:'smooth',block:'center'});}}if(action==='cancel-form')render();if(action==='month-prev'){calDate=new Date(calDate.getFullYear(),calDate.getMonth()-1,1);render();}if(action==='month-next'){calDate=new Date(calDate.getFullYear(),calDate.getMonth()+1,1);render();}if(action==='close-modal')closeModal();if(action==='save-job-detail')saveJobDetail();if(action==='export-payroll')exportPayroll();if(action==='import-ical'){if(!db.properties.length){showToast('Add a property first, then import its calendar.');setPage('properties');return;}const opts=propsOptions();showModal(`<button class="modal-close" data-action="close-modal">×</button><h2>Import a booking calendar</h2><p class="modal-desc">Upload an iCal (.ics) export for one property. Events become draft turnover jobs for you to review and assign.</p><div class="field"><label>PROPERTY</label><select id="icsProperty">${opts}</select></div><div class="form-actions"><button class="solid-btn" data-action="choose-ics">Choose .ics file</button></div>`);}if(action==='choose-ics')document.getElementById('icsInput').click();}
function saveJobDetail(){const j=db.jobs.find(x=>x.id===detailJobId);if(!j)return;const nextStatus=document.getElementById('jobStatus').value;const nextChecks=(j.checklist||[]).map((c,i)=>({...c,done:!!document.querySelector(`[data-check="${i}"]`)?.checked}));if(nextStatus==='completed'&&nextChecks.some(c=>!c.done)){showToast('Finish every checklist item before completing this turnover.');return;}j.cleanerId=document.getElementById('jobCleaner').value;j.status=nextStatus;j.fee=Number(document.getElementById('jobFee').value)||0;j.pay=Number(document.getElementById('jobPay').value)||0;j.damage=document.getElementById('jobDamage').value.trim();j.checklist=nextChecks;if(j.status==='completed'&&!j.completedAt){j.completedAt=new Date().toISOString();j.invoiceStatus='unpaid';db.messages.push({id:id(),text:`${propName(j.propertyId)} turnover marked complete. Owner invoice and cleaner pay are ready.`,author:teamName(j.cleanerId),date:today(),jobId:j.id});}if(j.status!=='completed')j.completedAt='';saveDB();closeModal();render();showToast(j.status==='completed'?'Turnover complete. Invoice and payroll updated.':'Job saved.');}
document.getElementById('opsNav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)setPage(b.dataset.page);});document.getElementById('opsContent').addEventListener('click',e=>{const p=e.target.closest('[data-page]'),a=e.target.closest('[data-action]'),job=e.target.closest('[data-job]'),stock=e.target.closest('[data-stock]'),invoice=e.target.closest('[data-invoice]'),delP=e.target.closest('[data-delete-property]'),delT=e.target.closest('[data-delete-team]'),thread=e.target.closest('[data-thread]'),review=e.target.closest('[data-escalation]'),prompt=e.target.closest('[data-prompt]');if(p)setPage(p.dataset.page);if(a)onAction(a.dataset.action);if(job)openJob(job.dataset.job);if(stock){const i=db.inventory.find(x=>x.id===stock.dataset.stock);i.qty=Math.max(0,(Number(i.qty)||0)+Number(stock.dataset.delta));saveDB();render();}if(invoice){const j=db.jobs.find(x=>x.id===invoice.dataset.invoice);j.invoiceStatus=invoice.dataset.pay;saveDB();render();showToast(`Invoice marked ${invoice.dataset.pay}.`);}if(thread){activeCommPropertyId=thread.dataset.thread;setPage('messages');}if(review)resolveOwnerReview(review.dataset.escalation,review.dataset.decision);if(prompt){const field=document.getElementById('unitMessage');if(field){field.value=prompt.dataset.prompt;field.focus();}}if(delP&&confirm('Remove this property? Existing turnovers will remain in the history.')){db.properties=db.properties.filter(x=>x.id!==delP.dataset.deleteProperty);saveDB();render();}if(delT&&confirm('Remove this team member? Existing payroll records will remain.')){db.team=db.team.filter(x=>x.id!==delT.dataset.deleteTeam);saveDB();render();}});
document.getElementById('opsContent').addEventListener('change',e=>{if(e.target.id==='commRole'){commRole=e.target.value;render();return;}if(e.target.dataset.setting){const key=e.target.dataset.setting;db.aiSettings[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;saveDB();showToast('Owner communication setting saved on this device.');}});
document.getElementById('opsContent').addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='unitComposer'){sendUnitMessage(d.get('text')||'');return;}if(f.id==='jobForm')addJobFromForm(f);if(f.id==='propertyForm'){const p={id:id(),name:d.get('name').trim(),client:d.get('client').trim(),address:d.get('address').trim(),unit:d.get('unit').trim(),rate:Number(d.get('rate'))||0,pay:Number(d.get('pay'))||0,access:d.get('access').trim(),linen:d.get('linen').trim(),checklist:d.get('checklist').split(/\n/).map(x=>x.trim()).filter(Boolean).map(text=>({text,done:false}))};db.properties.push(p);saveDB();render();showToast('Property added.');}if(f.id==='teamForm'){db.team.push({id:id(),name:d.get('name').trim(),role:d.get('role'),phone:d.get('phone').trim(),rate:Number(d.get('rate'))||0});saveDB();render();showToast('Team member added.');}if(f.id==='inventoryForm'){db.inventory.push({id:id(),name:d.get('name').trim(),category:d.get('category'),propertyId:d.get('propertyId'),qty:Number(d.get('qty'))||0,min:Number(d.get('min'))||0,unit:d.get('unit').trim()});saveDB();render();showToast('Inventory item added.');}if(f.id==='expenseForm'){db.expenses.push({id:id(),name:d.get('name').trim(),amount:Number(d.get('amount'))||0,category:d.get('category'),date:d.get('date')||today(),note:d.get('note').trim()});saveDB();render();showToast('Expense recorded.');}if(f.id==='messageForm'){db.messages.push({id:id(),author:d.get('author').trim()||'Team member',jobId:d.get('jobId'),text:d.get('text').trim(),date:today()});saveDB();render();showToast('Team update posted.');}});
document.getElementById('quickAdd').addEventListener('click',()=>{if(!db.properties.length){setPage('properties');showToast('Add a property first to schedule a turnover.');}else onAction('add-job');});document.getElementById('opsBackdrop').addEventListener('click',e=>{if(e.target.id==='opsBackdrop')closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
document.getElementById('opsModal').addEventListener('change',async e=>{if(e.target.id==='jobPhotos'){const j=db.jobs.find(x=>x.id===detailJobId);if(!j)return;try{const files=[...e.target.files];if(files.length>Math.max(0,6-j.photos.length))throw new Error('A turnover can store up to six photos.');const photos=await Promise.all(files.map(imageToSmallData));j.photos.push(...photos);if(!saveDB())return;openJob(j.id);showToast('Photo proof saved to the job.');}catch(error){showToast(error.message||'Could not read that image file.');}}});
const opsCommands=document.getElementById('opsCommands');function closeOpsCommands(){opsCommands.classList.remove('open');}document.querySelector('[data-ops-commands]').addEventListener('click',()=>opsCommands.classList.add('open'));opsCommands.addEventListener('click',e=>{if(e.target===opsCommands||e.target.closest('[data-ops-command-close]')){closeOpsCommands();return;}const b=e.target.closest('[data-page]');if(b){closeOpsCommands();setPage(b.dataset.page);}const a=e.target.closest('[data-action="add-job"]');if(a){closeOpsCommands();onAction('add-job');}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();opsCommands.classList.add('open');}if(e.key==='Escape')closeOpsCommands();});
document.getElementById('icsInput').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const p=document.getElementById('icsProperty')?.value;try{if(file.size>10*1024*1024)throw new Error('Calendar file is larger than the 10 MB limit.');importICS(await file.text(),p);}catch(error){showToast(error.message||'Could not read the calendar file.');}e.target.value='';});
function initSidebar(){let collapsed=false;try{collapsed=localStorage.getItem(OPS_SIDEBAR_KEY)==='true';}catch{}document.body.classList.toggle('sidebar-collapsed',collapsed);const names={overview:'Overview',schedule:'Schedule',properties:'Properties',team:'Team',inventory:'Inventory',finance:'Invoices and payroll',messages:'Unit inbox'};document.querySelectorAll('#opsNav .ops-link').forEach(link=>{const label=names[link.dataset.page]||'Open section';link.title=label;link.setAttribute('aria-label',label);});const button=document.getElementById('sidebarToggle');const update=()=>{const isCollapsed=document.body.classList.toggle('sidebar-collapsed');try{localStorage.setItem(OPS_SIDEBAR_KEY,isCollapsed?'true':'false');}catch{}button.setAttribute('aria-label',isCollapsed?'Expand sidebar':'Collapse sidebar');button.title=isCollapsed?'Expand sidebar':'Collapse sidebar';};button.addEventListener('click',update);button.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');button.title=collapsed?'Expand sidebar':'Collapse sidebar';}
initSidebar();render();
